import com.comsol.model.Model;
import com.comsol.model.physics.Physics;
import com.comsol.model.util.ModelUtil;
public final class LiNRR_M10A3_PdeProbe {public static void main(String[]a){Model m=ModelUtil.create("G");try{m.component().create("c",true);m.component("c").geom().create("g",3);m.component("c").geom("g").create("b","Block");m.component("c").geom("g").run();m.component("c").mesh().create("mesh");Physics p=m.component("c").physics().create("wp","WeakFormPDE","g",new String[]{"eta"});m.study().create("std");m.study("std").create("stat","Stationary");m.study("std").showAutoSequences("sol");String sol=m.study("std").getSolverSequences("SolverSequence")[0];dump("",m.sol(sol).feature());}finally{ModelUtil.remove("G");}}private static void dump(String pref,com.comsol.model.ModelEntityList<?> list){for(String t:list.tags()){try{com.comsol.model.SolverFeature e=(com.comsol.model.SolverFeature)list.get(t);System.out.println("NODE|"+pref+t+"|type="+e.getType()+"|props="+String.join(";",e.properties()));dump(pref+t+"/",e.feature());}catch(Exception ex){System.out.println("SKIP|"+pref+t+"|"+ex.getClass().getSimpleName());}}}}
